// WF12 Market Intelligence Report Builder config — DETERMINISTIC v0.1 skeleton (DEC-112/118).
// $0 by default: no Claude, no Telegram send, no external API. Reads WF10 output tabs, writes ONE
// market_intelligence_reports row (schema: docs/MARKET_INTELLIGENCE_REPORT_SCHEMA.md) + ONE agent_requests row.
function moscowIsoNow(){var m=new Date(Date.now()+10800000);return m.toISOString().replace('Z','+03:00');}
function moscowStamp(){var z=function(n){return String(n).padStart(2,'0');};var m=new Date(Date.now()+10800000);return m.getUTCFullYear()+z(m.getUTCMonth()+1)+z(m.getUTCDate())+'_'+z(m.getUTCHours())+z(m.getUTCMinutes())+z(m.getUTCSeconds());}
const stamp=moscowStamp();
return [{ json: {
  // --- hard-off defaults (DEC-112): the deterministic report is complete without any of these.
  enable_llm_summary:false,          // optional Claude summary branch (v0.2, DEC-122) — guarded, HTTP node DISABLED
  llm_approval_token:'',             // must equal 'I_APPROVE_CLAUDE_REPORT_SUMMARY' (explicit operator approval)
  llm_model:'claude-sonnet-4-6',     // project stack model (CLAUDE.md); pricing for cost tracking below
  llm_max_tokens:1200,               // hard output cap for the summary
  llm_input_price_per_mtok:3.0,      // USD per 1M input tokens (claude-sonnet-4-6)
  llm_output_price_per_mtok:15.0,    // USD per 1M output tokens (claude-sonnet-4-6)
  telegram_send:false,               // Telegram delivery — NOT implemented (delivered_to stays 'none')
  report_type:'on_demand',           // on_demand / weekly_digest / no_data_notice (auto-set on no_data)
  niche_id:'credit_brokerage',
  region:'Москва/МО',
  top_n:3,
  requested_by:'operator',
  report_id:'report_'+stamp,
  run_id:'wf12_'+stamp,
  agent_request_id:'wf12_req_'+stamp,
  created_at:moscowIsoNow()
}}];

// Deterministic Report Builder core (DEC-112/118): latest WF10 snapshot -> 20-col report row + Markdown.
// Facts only — every number/name comes from the WF10 tabs; nothing is invented; no contacts are surfaced.
function str(v){return v==null?'':String(v).trim();}
function num(v){var n=Number(v);return isFinite(n)?n:0;}
function rowsOf(name){try{return $(name).all().map(i=>i.json).filter(r=>r&&Object.keys(r).length);}catch(e){return [];}}
const cfg=$('Set Report Config').first().json;
const topN=Number(cfg.top_n)||3;
const profiles=rowsOf('Read competitor_profiles');
const angles=rowsOf('Read market_angles');
const signals=rowsOf('Read audience_activity_signals');
const plans=rowsOf('Read content_positioning_plan').filter(p=>str(p.plan_id));
// --- run selection: plan_id carries the WF10 run stamp (plan_<stamp> or plan_<stamp>_no_data; one plan per run)
function planStamp(p){return str(p.plan_id).replace(/^plan_/,'').replace(/_no_data$/,'');}
plans.sort((a,b)=>planStamp(a)<planStamp(b)?-1:1);
if(!plans.length){throw new Error('WF12: content_positioning_plan is empty — run WF10 at least once before building a report.');}
const latest=plans[plans.length-1];
const stamp=planStamp(latest);
const prev=plans.filter(p=>planStamp(p)!==stamp).pop()||null;
const prevStamp=prev?planStamp(prev):'';
const isNoData=/_no_data$/.test(str(latest.plan_id))||/rows=0/.test(str(latest.source_evidence));
const rowsAfter=(function(){const m=str(latest.source_evidence).match(/rows=(\d+)/);return m?Number(m[1]):(isNoData?0:0);})();
// --- snapshot filters: WF10 ids/notes carry the run stamp
const profNow=profiles.filter(p=>str(p.notes).indexOf('wf10_'+stamp)>=0||str(p.notes).indexOf(stamp)>=0);
const angNow=angles.filter(a=>str(a.angle_id).endsWith(stamp));
const angPrev=prevStamp?angles.filter(a=>str(a.angle_id).endsWith(prevStamp)):[];
const sigNow=signals.filter(s=>str(s.signal_id).endsWith(stamp));
// --- deterministic top lists
const topComp=profNow.slice().sort((a,b)=>(num(b.evidence_count)-num(a.evidence_count))||(num(b.source_confidence_score)-num(a.source_confidence_score))).slice(0,topN)
  .map(p=>str(p.competitor_name)+' (evidence '+num(p.evidence_count)+', conf '+num(p.source_confidence_score)+')');
function angleKey(a){return str(a.angle_id).replace(/^angle_/,'').replace(/_\d{8}_\d{6}$/,'');} // strip the trailing run stamp -> stable angle key across runs
const prevFreq={};for(const a of angPrev){prevFreq[angleKey(a)]=num(a.frequency);}
const topAng=angNow.slice().sort((a,b)=>num(b.frequency)-num(a.frequency)).slice(0,topN)
  .map(a=>{const k=angleKey(a);const f=num(a.frequency);let trend='·';
    if(prevStamp){const pf=prevFreq[k];trend=(pf===undefined)?'NEW':(f>pf?'↑':(f<pf?'↓':'='));}
    return str(a.angle_text)+' (x'+f+(prevStamp?(' '+trend):'')+')';});
const audSummary=sigNow.map(s=>str(s.platform)+': questions='+num(s.question_count)+', objections='+num(s.objection_count)+', complaints='+num(s.complaint_count)+', buying_intent='+num(s.buying_intent_count)+(str(s.top_pains)?(', pains: '+str(s.top_pains)):'')).join(' | ');
const NO_DATA_TEXT='no_data; broaden filters or source scope';
// --- v0.2 (DEC-122) extra deterministic sections — every value comes from WF10 rows; nothing invented.
const offersPrices=profNow.filter(p=>str(p.offers)||str(p.prices_terms)).slice(0,5)
  .map(p=>str(p.competitor_name)+': '+(str(p.offers)||'(оффер не извлечён)')+(str(p.prices_terms)?(' — '+str(p.prices_terms)):''));
const confScores=profNow.map(p=>num(p.source_confidence_score)).filter(n=>n>0);
const confAvg=confScores.length?Math.round(confScores.reduce((a,b)=>a+b,0)/confScores.length):0;
const confLine=confScores.length?('avg='+confAvg+', min='+Math.min.apply(null,confScores)+', max='+Math.max.apply(null,confScores)+' (по '+confScores.length+' профилям; правила: source_confidence_rules)'):'(нет профилей в снапшоте)';
const platformsSeen={};profNow.forEach(p=>str(p.platforms).split(/\s*,\s*/).forEach(x=>{if(x)platformsSeen[x]=(platformsSeen[x]||0)+1;}));
const platLine=Object.keys(platformsSeen).map(k=>k+' ('+platformsSeen[k]+')').join(', ')||'(none)';
const execSummary=isNoData
  ?'NO DATA: за окно отчёта нет строк после фильтров — расширить фильтры или источники.'
  :('За окно отчёта: '+profNow.length+' конкурентных профилей, '+angNow.length+' рыночных углов, '+sigNow.length+' агрегатов активности аудитории. Топ-конкурент: '+(topComp[0]||'(none)')+'. Топ-угол: '+(topAng[0]||'(none)')+'. Достоверность источников: '+confLine+'.');
const nextActions=isNoData
  ?'1. '+NO_DATA_TEXT+'\n2. Перезапустить WF10, затем WF12.'
  :'1. Проверить топ-конкурентов и углы в Google Sheets (competitor_profiles / market_angles).\n2. Утвердить план контента (content_positioning_plan).\n3. Отдельные шаги по одобрению: Claude-резюме (enable_llm_summary) и Telegram-доставка. Никакого аутрича: контакты в отчёт не выводятся (CONTACT_AND_OUTREACH_POLICY).';
// --- mandatory source-mix label (DEC-108): never imply all data was collected live in this run
const SOURCE_MIX='mixed: live + historical/manual + web pipeline';
const reportType=isNoData?'no_data_notice':str(cfg.report_type);
// --- deterministic Markdown render (the full report; v0.1 keeps it inline in result/notes, no file write)
const md=[
'# Market intelligence report '+str(cfg.report_id),
'',
'- niche: '+str(cfg.niche_id)+' · region: '+str(cfg.region)+' · WF10 run: wf10_'+stamp+(prevStamp?(' · prev: wf10_'+prevStamp):' · prev: (none — first report, no trends)'),
'- **Источники: '+SOURCE_MIX+'** · rows_after_filters='+rowsAfter,
'',
'## Executive summary',execSummary,
'',
isNoData?('**NO DATA:** '+NO_DATA_TEXT):[
'## Снапшот конкурентов (competitor_snapshot)','профилей в снапшоте: '+profNow.length+' · площадки: '+platLine,
'','### Топ конкурентов',topComp.length?topComp.map((c,i)=>(i+1)+'. '+c).join('\n'):'(none in snapshot)',
'','## Топ офферов и цен (top_offers_and_prices)',offersPrices.length?offersPrices.map((o,i)=>(i+1)+'. '+o).join('\n'):'(офферы/цены не извлечены в этом снапшоте)',
'','## Топ углов (market_angles_summary)',topAng.length?topAng.map((a,i)=>(i+1)+'. '+a).join('\n'):'(none in snapshot)',
'','## Активность аудитории (aggregate-only)',audSummary||'(no signals in snapshot)',
'','## План контента','plan: '+str(latest.plan_id)+' — '+str(latest.top_angles),
'','## Достоверность источников (source_confidence)',confLine
].join('\n'),
'',
'## Ограничения и source mix (limitations)',
'- '+SOURCE_MIX+' — агрегаты включают исторические/ручные записи, не только живой сбор последнего прогона.',
'- Тренды доступны только при >=2 прогонах WF10'+(prevStamp?'':' (этот отчёт — первый, трендов нет)')+'.',
'- Контакты и рекомендации по аутричу в отчёт не включаются (CONTACT_AND_OUTREACH_POLICY).',
'',
'## Следующие действия (next_actions)',nextActions,
'',
'_Deterministic report (DEC-112/122): факты только из WF10; no LLM by default, no contacts, no outreach. $0._'
].join('\n');
// --- 20-column market_intelligence_reports row (docs/MARKET_INTELLIGENCE_REPORT_SCHEMA.md)
return [{ json: {
  report_id:str(cfg.report_id),
  created_at:str(cfg.created_at),
  report_type:reportType,
  niche_id:str(cfg.niche_id),
  region:str(cfg.region),
  time_window_days:30,
  wf10_run_id:'wf10_'+stamp,
  prev_wf10_run_id:prevStamp?('wf10_'+prevStamp):'',
  source_mix:SOURCE_MIX,
  rows_after_filters:rowsAfter,
  top_competitors:isNoData?'':topComp.join(' | '),
  top_angles:isNoData?'':topAng.join(' | '),
  audience_summary:isNoData?'':audSummary,
  content_plan_ref:str(latest.plan_id),
  report_markdown_path:'',
  llm_summary:'',
  llm_recommendations:'',
  llm_cost_usd:0,
  delivered_to:'none',
  notes:(isNoData?('no_data_notice; recommendation: '+NO_DATA_TEXT+'; '):'')+'wf12 v0.1 deterministic skeleton (DEC-118); llm disabled (DEC-112); markdown inline below || '+md
}}];

// CLAUDE SUMMARY APPROVAL GATE (DEC-112/122) — fires on enable_llm_summary=true. INERT BY DEFAULT:
// throws unless the operator explicitly armed the run, and even then the downstream HTTP node ships
// DISABLED with no credential — enabling it is a second deliberate operator action in the n8n editor.
// Claude is the business-interpretation layer ON TOP of the deterministic WF10 fact core (DEC-112):
// it may only summarize the deterministic report — no invented facts, no contacts, no outreach.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Report Config').first().json;
if(str(cfg.llm_approval_token)!=='I_APPROVE_CLAUDE_REPORT_SUMMARY'){
  throw new Error('WF12 Claude gate: operator approval token missing. The optional Claude summary requires: llm_approval_token=I_APPROVE_CLAUDE_REPORT_SUMMARY in Set Report Config, an Anthropic credential bound in n8n (never in this file), and ENABLING the disabled HTTP node. Deterministic report stays $0 by default (DEC-112). Cost must be recorded in agent_requests + docs/COSTS_AND_LIMITS.md.');
}
return $input.all();

// Final run summary. No external calls.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Report Config').first().json;
const rep=$('Build Deterministic Report').first().json;
return [{ json: {
  workflow:'12 - Market Intelligence Report Builder (deterministic skeleton)',
  report_id:str(rep.report_id),
  report_type:str(rep.report_type),
  wf10_run_id:str(rep.wf10_run_id),
  prev_wf10_run_id:str(rep.prev_wf10_run_id)||'(none)',
  rows_after_filters:rep.rows_after_filters,
  top_competitors:str(rep.top_competitors),
  top_angles:str(rep.top_angles),
  source_mix:str(rep.source_mix),
  enable_llm_summary:false,
  llm_cost_usd:0,
  telegram_send:false,
  delivered_to:'none',
  next_action:(str(rep.report_type)==='no_data_notice')?'no_data report written; broaden filters/source scope before the next WF10 run.':'Inspect market_intelligence_reports + agent_requests rows. Trends need >=2 WF10 runs. Claude summary / Telegram delivery = separate gated steps.'
}}];

// Build the evidence-bound Claude summary prompt (DEC-122). FACTS ONLY: the prompt contains the
// deterministic report fields — never raw_market_records text, never contact fields. Hard rules in the
// system prompt forbid invented facts/competitors/numbers, contacts, and outreach recommendations.
function str(v){return v==null?'':String(v).trim();}
function cut(s,n){s=str(s);return s.length>n?s.slice(0,n):s;}
const cfg=$('Set Report Config').first().json;
const rep=$('Build Deterministic Report').first().json;
const sys='Ты — аналитик рынка. Тебе дан ДЕТЕРМИНИРОВАННЫЙ отчёт (факты, собранные пайплайном). Твоя задача: краткое бизнес-резюме и интерпретация ТОЛЬКО на основе этих фактов. ЖЁСТКИЕ ПРАВИЛА: (1) не выдумывай факты, конкурентов, цифры, тренды; (2) не упоминай и не выводи контакты; (3) не рекомендуй аутрич/рассылки/обзвоны; (4) если данных мало — так и скажи; (5) ответ на русском, до 250 слов, секции: Итог, Интерпретация, Риски/пробелы данных.';
const facts={ report_id:str(rep.report_id), niche:str(rep.niche_id), region:str(rep.region), wf10_run_id:str(rep.wf10_run_id), prev_wf10_run_id:str(rep.prev_wf10_run_id), rows_after_filters:rep.rows_after_filters, source_mix:str(rep.source_mix), top_competitors:str(rep.top_competitors), top_angles:str(rep.top_angles), audience_summary:str(rep.audience_summary), content_plan_ref:str(rep.content_plan_ref) };
const body={ model:str(cfg.llm_model)||'claude-sonnet-4-6', max_tokens:Number(cfg.llm_max_tokens)||1200, system:sys, messages:[{ role:'user', content:'Детерминированный отчёт (JSON, единственный источник фактов):\n'+cut(JSON.stringify(facts),6000) }] };
return [{ json: Object.assign({}, rep, { llm_request_body: body }) }];

// Merge the Claude summary into the report row + track cost (DEC-122). If the HTTP placeholder is
// still DISABLED, items pass through WITHOUT a Claude response body — this node then throws, so no
// fabricated summary can ever be written. With a real response: extract text + usage, compute cost
// (claude-sonnet-4-6: $3/MTok in, $15/MTok out), and fill llm_summary / llm_cost_usd on the 20-col row.
function str(v){return v==null?'':String(v).trim();}
const cfg=$('Set Report Config').first().json;
const rep=$('Build Deterministic Report').first().json;
const resp=$input.first().json;
const content=resp&&Array.isArray(resp.content)?resp.content:null;
if(!content){
  throw new Error('WF12 Claude merge: no API response — the Claude HTTP placeholder node is DISABLED (inert by design, DEC-122). Enable it with a bound n8n credential only after operator approval; default runs write the deterministic report ($0).');
}
let text='';for(const b of content){ if(b&&b.type==='text'&&str(b.text))text+=b.text; }
if(resp.stop_reason==='refusal'||!str(text)){ throw new Error('WF12 Claude merge: empty or refused summary (stop_reason='+str(resp.stop_reason)+') — keep the deterministic report; investigate before retrying.'); }
const u=resp.usage||{};
const inTok=Number(u.input_tokens)||0, outTok=Number(u.output_tokens)||0;
const cost=Math.round(((inTok*(Number(cfg.llm_input_price_per_mtok)||3.0)+outTok*(Number(cfg.llm_output_price_per_mtok)||15.0))/1000000)*10000)/10000;
return [{ json: Object.assign({}, rep, {
  llm_summary:str(text).slice(0,4000),
  llm_recommendations:'',
  llm_cost_usd:cost,
  notes:str(rep.notes)+' || llm_summary added (model='+(str(cfg.llm_model)||'claude-sonnet-4-6')+', input_tokens='+inTok+', output_tokens='+outTok+', cost_usd='+cost+'); evidence-bound prompt, no invented facts/contacts/outreach (DEC-122).'
}) }];
